/// An exploration, as cortext's exploration registry stores it: one governed
/// object per program a mission asked to run, homed in the `.models` system
/// directory beside `ModelManifest`, `OntologyDeclaration` and `Mission` (the
/// same governed-object recipe), with an ACL the owner controls and the
/// platform's own revision history.
///
/// The object is a *reference*, like the other three: the program is a Drive
/// file named here by id, content revision and sha256, and the fields a reader
/// lists on (the mission it belongs to, its status, who asked for it and when)
/// are projected once per source revision into the `explorations` registry
/// (registry.fbs), so nothing on a read path opens the program. The program is
/// an authored text file — the registry reads it as text, not as a structured
/// source. `result_digest` is the one line the run left behind; the result
/// itself is not here and does not revise the object.
#[derive(Default, PartialEq, Debug, Clone, Hash, Eq, Serialize, Deserialize)]
pub struct Exploration {
    /// The principal whose write this revision is (oid).
    pub authored_by: Option<String>,
    /// When the exploration was created, ms since the epoch (UTC).
    pub created_at: i64,
    /// The exploration's id, permanent and unique; the object id derives from
    /// it, so a re-registration of the same exploration revises the same
    /// object.
    pub exploration_id: String,
    /// The mission the exploration was run for (its authored `mission_id`).
    pub mission_id: Option<String>,
    /// That file's content revision at this write.
    pub program_cid: Option<ContentId>,
    /// The Drive file object holding the stored program.
    pub program_id: ObjectId,
    /// sha256 (hex) of the program bytes; the projector verifies it.
    pub program_sha256: String,
    /// The principal who asked for the exploration (oid).
    pub requested_by: Option<String>,
    /// A one-line digest of what the run produced, empty until it ran.
    pub result_digest: Option<String>,
    /// Where the exploration is in its life: what a board filters on.
    pub status: Option<String>,
}

impl Exploration {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsExploration<'a>> {
        use crate::types::generated::exploration_generated::ExplorationBuilder as FbsExplorationBuilder;

        let authored_by_offset = self.authored_by.as_ref().map(|s| builder.create_string(s));
        let exploration_id_offset = builder.create_string(&self.exploration_id);
        let mission_id_offset = self.mission_id.as_ref().map(|s| builder.create_string(s));
        let program_cid_offset = self.program_cid.as_ref().map(|o| o.serialize_to(builder));
        let program_id_offset = self.program_id.serialize_to(builder);
        let program_sha256_offset = builder.create_string(&self.program_sha256);
        let requested_by_offset = self.requested_by.as_ref().map(|s| builder.create_string(s));
        let result_digest_offset = self
            .result_digest
            .as_ref()
            .map(|s| builder.create_string(s));
        let status_offset = self.status.as_ref().map(|s| builder.create_string(s));

        let mut bldr = FbsExplorationBuilder::new(builder);
        if let Some(offset) = authored_by_offset {
            bldr.add_authored_by(offset);
        }
        bldr.add_created_at(self.created_at);
        bldr.add_exploration_id(exploration_id_offset);
        if let Some(offset) = mission_id_offset {
            bldr.add_mission_id(offset);
        }
        if let Some(offset) = program_cid_offset {
            bldr.add_program_cid(offset);
        }
        bldr.add_program_id(program_id_offset);
        bldr.add_program_sha256(program_sha256_offset);
        if let Some(offset) = requested_by_offset {
            bldr.add_requested_by(offset);
        }
        if let Some(offset) = result_digest_offset {
            bldr.add_result_digest(offset);
        }
        if let Some(offset) = status_offset {
            bldr.add_status(offset);
        }
        bldr.finish()
    }
}

impl From<FbsExploration<'_>> for Exploration {
    fn from(fbs: FbsExploration<'_>) -> Self {
        let authored_by = fbs.authored_by().map(ToOwned::to_owned);
        let created_at = fbs.created_at();
        let exploration_id = fbs.exploration_id().to_owned();
        let mission_id = fbs.mission_id().map(ToOwned::to_owned);
        let program_cid = fbs.program_cid().map(ContentId::from);
        let program_id = ObjectId::from(fbs.program_id());
        let program_sha256 = fbs.program_sha256().to_owned();
        let requested_by = fbs.requested_by().map(ToOwned::to_owned);
        let result_digest = fbs.result_digest().map(ToOwned::to_owned);
        let status = fbs.status().map(ToOwned::to_owned);
        Self {
            authored_by,
            created_at,
            exploration_id,
            mission_id,
            program_cid,
            program_id,
            program_sha256,
            requested_by,
            result_digest,
            status,
        }
    }
}

impl crate::FbsSerde for Exploration {
    fn to_fbs_bytes(&self) -> Vec<u8> {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = self.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }

    fn from_fbs_bytes(bytes: &[u8]) -> Result<Self, flatbuffers::InvalidFlatbuffer> {
        let opts = flatbuffers::VerifierOptions {
            max_tables: 100_000_000,
            ..Default::default()
        };
        let fbs = flatbuffers::size_prefixed_root_with_opts::<FbsExploration>(&opts, bytes)?;
        Ok(Self::from(fbs))
    }
}

